"use strict";exports.id=164,exports.ids=[164],exports.modules={20164:(a,b,c)=>{c.r(b),c.d(b,{articleDetails:()=>d});let d={slug:"how-to-crop-images-for-social-media",title:"How to Crop Images for Every Social Media Platform",metaDesc:"Complete 2025 guide to social media image dimensions. Crop images to the right aspect ratio for Instagram, YouTube, TikTok, LinkedIn, and more.",publishDate:"2025-06-11",category:"image",categoryLabel:"Image Tools",relatedToolSlugs:["image-cropper","image-resizer","social-post-size-checker"],content:"\n<h2>Why Aspect Ratios Matter on Social Media</h2>\n<p>Every social media platform uses a specific display grid. Upload an image with the wrong proportions and the platform auto-crops it — often cutting off faces, text, or the focal point of your composition. Getting the aspect ratio right before posting ensures your content looks intentional and professional.</p>\n\n<h2>2025 Social Media Image Dimensions Cheat Sheet</h2>\n\n<h3>Instagram</h3>\n<ul>\n  <li><strong>Feed post (square):</strong> 1080 \xd7 1080 px (1:1)</li>\n  <li><strong>Feed post (portrait):</strong> 1080 \xd7 1350 px (4:5) — takes up more screen space</li>\n  <li><strong>Feed post (landscape):</strong> 1080 \xd7 566 px (1.91:1)</li>\n  <li><strong>Stories / Reels:</strong> 1080 \xd7 1920 px (9:16)</li>\n  <li><strong>Profile photo:</strong> 320 \xd7 320 px</li>\n</ul>\n\n<h3>YouTube</h3>\n<ul>\n  <li><strong>Thumbnails:</strong> 1280 \xd7 720 px (16:9)</li>\n  <li><strong>Channel banner:</strong> 2560 \xd7 1440 px (safe zone: center 1546 \xd7 423 px)</li>\n  <li><strong>Profile photo:</strong> 800 \xd7 800 px</li>\n</ul>\n\n<h3>Facebook</h3>\n<ul>\n  <li><strong>Feed post (link):</strong> 1200 \xd7 630 px (1.91:1)</li>\n  <li><strong>Feed post (square):</strong> 1080 \xd7 1080 px</li>\n  <li><strong>Cover photo:</strong> 851 \xd7 315 px (desktop) / 640 \xd7 360 px (mobile)</li>\n</ul>\n\n<h3>LinkedIn</h3>\n<ul>\n  <li><strong>Feed post:</strong> 1200 \xd7 627 px (recommended)</li>\n  <li><strong>Profile banner:</strong> 1584 \xd7 396 px</li>\n  <li><strong>Company logo:</strong> 300 \xd7 300 px</li>\n</ul>\n\n<h3>TikTok</h3>\n<ul>\n  <li><strong>Video cover / profile:</strong> 200 \xd7 200 px</li>\n  <li><strong>Video:</strong> 1080 \xd7 1920 px (9:16)</li>\n</ul>\n\n<h2>How to Crop Images for Social Media</h2>\n<ol>\n  <li>Open the <a href=\"/tools/image/image-cropper\">Image Cropper</a>.</li>\n  <li>Upload your image.</li>\n  <li>Select the aspect ratio preset that matches your target platform (1:1 for Instagram square, 16:9 for YouTube thumbnail, etc.).</li>\n  <li>Drag the crop box to frame your subject correctly.</li>\n  <li>Click <strong>Crop &amp; Download</strong>.</li>\n</ol>\n\n<h2>Pro Tip: Shoot Vertically for Maximum Flexibility</h2>\n<p>If you're taking photos specifically for social media, shoot in portrait orientation (vertical). A 9:16 vertical image can be cropped to 4:5, 1:1, or 16:9 without losing the main subject. A landscape photo can't easily crop into vertical formats without losing most of the image.</p>\n    "}}};